import argparse
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import re


def time(s, tz=None):
    value = datetime.fromisoformat(s)
    if value.tzinfo is None:
        if tz is None:
            raise ValueError()
        value = value.replace(tzinfo=tz)
    return value


def reject_constant(value):
    raise ValueError('invalid JSON constant: ' + value)


def summarize(node, now):
    out = dict(v=1, routines=[], schedule=[], counts={'routines': dict.fromkeys(('running', 'never', 'failed', 'overdue', 'ok'), 0), 'schedule': dict.fromkeys(('interrupted', 'due', 'pending'), 0)}, bad=[])
    for table in ('routines', 'schedule'):
        path = node / 'wf' / (table + '.json')
        if not path.exists():
            continue
        def reject(row, why):
            out['bad'].append(dict(table=table, row=row, why=why))
        try:
            data = json.loads(path.read_text(), parse_constant=reject_constant)
            if not isinstance(data, dict) or data.get('contract') != 'wf-table/1' or not isinstance(data.get('rows'), list) or not isinstance(data.get('columns'), list) or not all(isinstance(c, str) for c in data['columns']):
                raise ValueError()
        except (ValueError, OSError):
            reject(None, 'bad_table')
            continue
        seen = set()
        for i, row in enumerate(data['rows']):
            # Remember every nonempty string name, even in an invalid first row.
            name = row.get('name') if isinstance(row, dict) else None
            duplicate = isinstance(name, str) and bool(name) and name in seen
            if isinstance(name, str) and name:
                seen.add(name)
            if duplicate:
                reject(i, 'dup_name')
                continue
            fields = ('name', 'every', 'last_time', 'last_code') if table == 'routines' else ('name', 'at', 'claimed')
            if not isinstance(row, dict) or any(not isinstance(v, str) for v in row.values()) or any(k not in row for k in fields) or not name:
                reject(i, 'bad_row')
                continue
            try:
                at = time(row['last_time'], now.tzinfo) if table == 'routines' and row['last_time'] else time(row['at'], now.tzinfo) if table == 'schedule' else None
            except ValueError:
                reject(i, 'bad_row')
                continue
            if table == 'routines':
                m = re.fullmatch(r'([1-9][0-9]*)([rsmhd])', row['every'])
                if not m:
                    reject(i, 'bad_row')
                    continue
                code = row['last_code']
                if code not in ('', 'running') and not re.fullmatch(r'[+-]?[0-9]+', code):
                    reject(i, 'bad_row')
                    continue
                code = None if code == '' else code if code == 'running' else int(code)
                seconds = int(m[1]) * {'s': 1, 'm': 60, 'h': 3600, 'd': 86400}.get(m[2], 0)
                nxt = at + timedelta(seconds=seconds) if at is not None and m[2] != 'r' else None
                state = 'running' if code == 'running' else 'never' if at is None else 'failed' if type(code) is int and code != 0 else 'overdue' if nxt is not None and now >= nxt else 'ok'
                item = dict(name=name, every=row['every'], last_time=row['last_time'] or None, last_code=code, state=state, next=nxt.astimezone(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ') if nxt else None)
            else:
                state = 'interrupted' if row['claimed'] else 'due' if at <= now else 'pending'
                item = dict(name=name, at=row['at'], state=state)
            out[table].append(item)
            out['counts'][table][state] += 1
        out[table].sort(key=lambda x: x['name'])
    out['bad'].sort(key=lambda x: (x['table'], -1 if x['row'] is None else x['row'], x['why']))
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('node', type=Path)
    ap.add_argument('--now', required=True)
    a = ap.parse_args()
    try:
        now = time(a.now)
    except ValueError:
        return 2
    if not a.node.is_dir():
        return 2
    print(json.dumps(summarize(a.node, now)))
    return 0
